// 只测独立字段编解码与坏格式；人工载荷不代表已过租约、客户、司法资格或真实开店旅程。
#include "resident/domains/commerce/private_shop_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0;
void check(bool value,const char* label){++checks;if(!value)throw std::runtime_error(label);}
BoundaryValue& field(BoundaryValue& object,const StableId& key){for(auto& row:*object.as<BoundaryValue::Dict>())if(row.first==key)return row.second;throw std::runtime_error("missing test field");}
// 所有表均放一项以防空表往返掩盖漏字段；业务史仍留给实际同候选组件。
PrivateShopState sample(){PrivateShopState s;s.initialized_tick=4;s.last_step_tick=8;PrivateShopRecord shop;shop.id="private_shop:20";shop.wallet_id="private_shop_wallet:20";shop.inventory_id="private_shop_inventory:20";shop.rent_obligation_id="private_shop_rent:21";shop.terms={"premises.a","place.market","owner","landlord","wallet.owner","wallet.landlord","market.a",900,300,200,2,"rate.rent"};shop.opened_tick=4;shop.markup_basis_points=500;shop.meeting={"owner","landlord","session:18","dialogue.lease","node.agree","place.market","role.lessor"};shop.qualification.minimum_commerce_xp=200;shop.qualification.minimum_commerce_level=2;shop.qualification.permit_fact_id="political_shop_permit:10";shop.qualification.clearance_fact_id="political_shop_clearance:11";shop.qualification.original_clients.push_back({{Owner::Kind::actor,"client",{}},{SubjectKind::actor,"receiver"},"task:2","settlement:3","template.delivery","payment:4",2,{"delivery:1"}});s.shops.insert(shop.id,shop);s.capital.insert("private_shop_capital:22",{"private_shop_capital:22",shop.id,"owner","wallet.owner",shop.wallet_id,5,20});s.markups.insert("private_shop_markup:23",{"private_shop_markup:23",shop.id,"owner",6,0,500});PrivateShopOrderRecord order;order.id="private_shop_order:24";order.policy_id="order.policy";order.issued_tick=7;order.valid_through_tick=9;order.terms={order.id,shop.id,"owner",{Owner::Kind::actor,"client",{}},"template.procurement","grain",shop.inventory_id,shop.wallet_id,"client.bag","client.wallet",4,30,-1,15};order.client_declaration={"owner","client","meeting:2","client.dialogue","buy","place.market","client.role"};s.orders.orders.insert(order.id,order);return s;}
}
int main(){try{
 auto state=sample();auto raw=encode_private_shop_state(state);auto restored=decode_private_shop_state(raw);check(restored.ok,"decode populated shop");check(compare_boundary(raw,encode_private_shop_state(restored.value)).exact(),"exact JSON roundtrip");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);check(visit_private_shop_checkpoint(writer,restored.value).ok&&writer.finish().ok,"write typed binary");PrivateShopState cold;const auto& input=bytes;CodecVisitor reader(input);check(visit_private_shop_checkpoint(reader,cold).ok&&reader.finish().ok,"read typed binary");check(compare_boundary(raw,encode_private_shop_state(cold)).exact(),"exact binary roundtrip");
 auto bad=raw;bad.as<BoundaryValue::Dict>()->emplace_back("version",BoundaryValue{Integer{1}});check(!decode_private_shop_state(bad).ok,"duplicate root field");bad=raw;field(bad,"version")=BoundaryValue{Integer{2}};check(!decode_private_shop_state(bad).ok,"unknown version");bad=raw;bad.as<BoundaryValue::Dict>()->emplace_back("cash",BoundaryValue{Integer{9999}});check(!decode_private_shop_state(bad).ok,"parallel balance field");bad=raw;field(bad,"capital")=BoundaryValue{BoundaryValue::Array{}};check(!decode_private_shop_state(bad).ok,"table cannot be array");
 bad=raw;auto& shop=field(field(bad,"shops"),"private_shop:20");shop.as<BoundaryValue::Dict>()->emplace_back("opened_tick",BoundaryValue{Integer{4}});check(!decode_private_shop_state(bad).ok,"duplicate nested tick");bad=raw;field(field(field(bad,"shops"),"private_shop:20"),"qualification")=BoundaryValue{};check(!decode_private_shop_state(bad).ok,"missing qualification not initialized");bad=raw;auto& funds=field(bad,"capital");const auto first=funds.as<BoundaryValue::Dict>()->front();funds.as<BoundaryValue::Dict>()->push_back(first);check(!decode_private_shop_state(bad).ok,"duplicate capital record");
 auto truncated=bytes;truncated.pop_back();const auto& truncated_input=truncated;CodecVisitor short_reader(truncated_input);PrivateShopState short_state;auto short_result=visit_private_shop_checkpoint(short_reader,short_state);check(!short_result.ok||!short_reader.finish().ok,"truncated binary rejected");auto trailing=bytes;trailing.push_back(0);const auto& trailing_input=trailing;CodecVisitor long_reader(trailing_input);PrivateShopState long_state;check(visit_private_shop_checkpoint(long_reader,long_state).ok&&!long_reader.finish().ok,"trailing binary rejected");
 std::cout<<checks<<"/0 codec format checks\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
